use biome_analyze::{
    context::RuleContext, declare_rule, Rule, RuleDiagnostic, RuleSource, RuleSourceKind,
};
use biome_console::markup;
use biome_js_syntax::{AnyJsExpression, JsCallExpression, JsImport, JsReferenceIdentifier};
use biome_rowan::{AstNode, TextRange};

declare_rule! {
    /// Checks that the assertion function, for example `expect`, is placed inside an `it()` function call.
    ///
    /// Placing (and using) the `expect` assertion function can result in unexpected behaviors when executing your testing suite.
    ///
    /// The rule will check for the following assertion calls:
    /// - `expect`
    /// - `assert`
    /// - `assertEquals`
    ///
    /// However, the rule will check the assertion calls only if:
    /// - the assertion call isn't imported. The rule skips imported assertion calls, unless they are imported by a well-known
    /// package such as `chai`, `node:assert`, `node:assert/strict`, `bun:test`, `vitest` and Deno standard library.
    /// - the assertion is placed inside a function that isn't a testing function such as `it`, `test`, `Deno.test`.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```js,expect_diagnostic
    /// describe("describe", () => {
    ///     expect()
    /// })
    /// ```
    ///
    /// ```js,expect_diagnostic
    /// import assert from "node:assert";
    /// describe("describe", () => {
    ///     assert.equal()
    /// })
    /// ```
    ///
    /// ```js,expect_diagnostic
    /// test.each([1, 2, 3])('test', (a, b, expected) => {
    ///     expect(a + b).toBe(expected)
    /// })
    /// ```
    ///
    /// ### Valid
    ///
    /// ```js
    /// import assert from "node:assert";
    /// describe("describe", () => {
    ///     it("it", () => {
    ///         assert.equal()
    ///     })
    /// })
    /// ```
    ///
    /// ```js
    /// describe("describe", () => {
    ///     it("it", () => {
    ///         expect()
    ///     })
    /// })
    /// ```
    ///
    /// ```js
    /// test.each([1, 2, 3])('test', (a, b, expected) => {
    ///     it("it", () => {
    ///         expect(a + b).toBe(expected)
    ///     })
    /// })
    /// ```
    ///
    pub NoMisplacedAssertion {
        version: "next",
        name: "noMisplacedAssertion",
        source: RuleSource::EslintJest("no-standalone-expect"),
        source_kind: RuleSourceKind::Inspired,
        recommended: false,
    }
}

/// The name of the assertion functions/objects that this rule recognizes.
const ASSERTION_FUNCTION_NAMES: [&str; 3] = ["expect", "assertEquals", "assert"];

/// The specifiers that expose the recognized assertion functions.
const SPECIFIERS: [&str; 5] = [
    "chai",
    "node:assert",
    "node:assert/strict",
    "bun:test",
    "vitest",
];

impl Rule for NoMisplacedAssertion {
    type Query = Semantic<JsCallExpression>;
    type State = TextRange;
    type Signals = Option<Self::State>;
    type Options = ();

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let query = ctx.query();
        let model = ctx.model();
        let callee = query.callee().ok()?;

        let assertion_call = callee.get_callee_object_name()?;

        if !ASSERTION_FUNCTION_NAMES.contains(&assertion_call.text_trimmed()) {
            return None;
        }

        // If the assertion function is a binding, we only want to flag it if it
        // comes from a well-known assertion package. Local bindings (helper
        // functions, variables, etc.) are ignored.
        if let Some(reference) = get_callee_reference(&callee) {
            if let Some(binding) = model.binding(&reference) {
                let import = binding
                    .tree()
                    .syntax()
                    .ancestors()
                    .find_map(JsImport::cast);

                // The binding is a local declaration, not an import.
                let import = import?;

                let source = import.source_text().ok()?;
                let source = source.text();

                if !is_known_assertion_specifier(source) {
                    return None;
                }
            }
        }

        // The assertion is correctly placed if it is nested inside a testing
        // function such as `it()`, `test()` or `Deno.test()`.
        let is_inside_a_test = query
            .syntax()
            .ancestors()
            .filter_map(JsCallExpression::cast)
            .filter_map(|call_expression| {
                let callee = call_expression.callee().ok()?;
                Some(is_test_function_call(&callee))
            })
            .any(|is_test| is_test);

        if is_inside_a_test {
            return None;
        }

        Some(assertion_call.text_trimmed_range())
    }

    fn diagnostic(_: &RuleContext<Self>, range: &Self::State) -> Option<RuleDiagnostic> {
        Some(
            RuleDiagnostic::new(
                rule_category!(),
                range,
                markup! {
                    "The assertion isn't inside a "<Emphasis>"it()"</Emphasis>", "<Emphasis>"test()"</Emphasis>" or "<Emphasis>"Deno.test()"</Emphasis>" function call."
                },
            )
            .note(markup! {
                "This will result in unexpected behaviours from your test suite."
            })
            .note(markup! {
                "Move the assertion inside a "<Emphasis>"it()"</Emphasis>", "<Emphasis>"test()"</Emphasis>" or "<Emphasis>"Deno.test()"</Emphasis>" function call."
            }),
        )
    }
}

/// Returns the reference identifier used to call the assertion function, if any.
///
/// For `expect(...)` it returns the `expect` reference, and for `assert.equal(...)`
/// it returns the `assert` reference.
fn get_callee_reference(callee: &AnyJsExpression) -> Option<JsReferenceIdentifier> {
    match callee {
        AnyJsExpression::JsIdentifierExpression(identifier) => identifier.name().ok(),
        AnyJsExpression::JsStaticMemberExpression(member) => member
            .object()
            .ok()?
            .as_js_identifier_expression()?
            .name()
            .ok(),
        _ => None,
    }
}

/// Returns `true` if the `source` matches one of the well-known assertion specifiers.
fn is_known_assertion_specifier(source: &str) -> bool {
    SPECIFIERS.contains(&source) || is_deno_assertion_specifier(source)
}

/// Returns `true` if the `source` is a Deno standard library assertion URL,
/// for example `https://deno.land/std@0.220.0/assert/mod.ts`.
fn is_deno_assertion_specifier(source: &str) -> bool {
    source.starts_with("https://deno.land/std") && source.contains("assert")
}

/// Returns `true` if `callee` refers to a testing function where an assertion is
/// allowed, namely `it()`, `test()` or `Deno.test()`.
fn is_test_function_call(callee: &AnyJsExpression) -> bool {
    let Some(object_name) = callee.get_callee_object_name() else {
        return false;
    };

    match object_name.text_trimmed() {
        "it" | "test" => true,
        // `Deno.test()`
        "Deno" => callee
            .get_callee_member_name()
            .is_some_and(|member| member.text_trimmed() == "test"),
        _ => false,
    }
}
